
.world-section {
  border-bottom: 3px solid var(--c-granite);
  padding: 14px 16px;
  background-color: var(--c-mint-cream);
}

.meta-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 10px;
  font-weight: bold;
  font-size: 0.9rem;
  font-family: var(--font-round);
  border-bottom: 1.5px dashed var(--c-grey-olive);
  padding-bottom: 8px;
  flex-wrap: wrap;
  gap: 8px;
}

.character-list {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding: 4px 0;
}

.character-badge {
  background: #fff;
  border: 1.5px solid var(--c-granite);
  border-radius: var(--radius-md);
  padding: 8px 10px;
  min-width: 150px;
  flex: 1;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 3px;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.character-badge:hover {
  transform: translateY(-2px);
  box-shadow: 3px 3px 8px rgba(60, 73, 63, 0.15);
}

.character-badge::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  background-color: var(--c-celadon);
  border-radius: var(--radius-md) 0 0 var(--radius-md);
}

.character-name {
  display: block;
  font-weight: bold;
  margin-bottom: 2px;
  padding-left: 8px;
  font-size: 0.85rem;
  font-family: var(--font-round);
}

.character-outfit {
  display: block;
  font-size: 0.75rem;
  color: var(--c-granite);
  padding-left: 8px;
}

.character-state {
  display: block;
  font-size: 0.75rem;
  color: var(--c-grey-olive);
  padding-left: 8px;
}

.character-thought {
  display: block;
  font-size: 0.7rem;
  color: var(--c-grey-olive);
  font-style: italic;
  padding-left: 8px;
  margin-top: 2px;
}

.empty-state {
  text-align: center;
  color: var(--c-grey-olive);
  padding: 12px;
  font-style: italic;
  font-size: 0.85rem;
}

@media (max-width: 600px) {
  .meta-row {
    flex-direction: column;
    gap: 5px;
  }

  .character-list {
    flex-direction: column;
  }

  .character-badge {
    min-width: auto;
  }
}
