
.witch-stats {
  padding: 14px 16px;
  background: #fff;
  border-bottom: 2px solid var(--c-granite);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-label {
  font-weight: bold;
  font-size: 0.85rem;
  min-width: 64px;
  font-family: var(--font-round);
}

.stat-track {
  flex: 1;
  height: 14px;
  border: 1.5px solid var(--c-granite);
  border-radius: var(--radius-lg);
  background: var(--c-mint-cream);
  position: relative;
  overflow: hidden;
}

.stat-fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  border-radius: var(--radius-lg);
  transition: width 0.5s cubic-bezier(0.4, 0, 0.2, 1);

  &.intimacy {
    background: linear-gradient(90deg, #ff9999, #ff6b6b);
  }

  &.trust {
    background: var(--c-celadon);
  }
}

.stat-value-group {
  display: flex;
  align-items: center;
  gap: 6px;
  filter: blur(4px);
  transition: filter 0.3s ease;
  cursor: pointer;
  user-select: none;
}

.stat-value-group.unlocked {
  filter: blur(0);
  cursor: default;
}

.stat-value {
  font-weight: bold;
  font-size: 0.85rem;
  min-width: 60px;
  text-align: center;
}

.stat-button {
  width: 24px;
  height: 22px;
  padding: 0;
  border: 1.5px solid var(--c-granite);
  background: var(--c-mint-cream);
  color: var(--c-granite);
  font-family: inherit;
  font-weight: bold;
  line-height: 1;
  cursor: pointer;
  box-shadow: 2px 2px 0px rgba(60, 73, 63, 0.16);
  transition: all 0.15s ease;
  pointer-events: none;
}

.stat-value-group.unlocked .stat-button {
  pointer-events: auto;
}

.stat-button:active:not(:disabled) {
  transform: translate(1px, 1px);
  box-shadow: 1px 1px 0px rgba(60, 73, 63, 0.16);
}

.stat-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
}

.stat-button:focus-visible {
  outline: 2px dashed var(--c-granite);
  outline-offset: 2px;
}

.stat-info {
  display: flex;
  gap: 16px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-grey-olive);
  flex-wrap: wrap;
}

.info-item {
  font-size: 0.8rem;
}

.virgin-item {
  filter: blur(4px);
  transition: filter 0.3s ease;
  cursor: pointer;
  user-select: none;
}

.virgin-item.unlocked {
  filter: blur(0);
  cursor: default;
}

.info-label {
  color: var(--c-grey-olive);
  margin-right: 4px;
}

.info-value {
  font-weight: bold;
  color: var(--c-granite);
}

.no-witch-selected {
  padding: 16px;
  text-align: center;
  background: #fff;
  border-bottom: 2px solid var(--c-granite);
  color: var(--c-grey-olive);
  font-style: italic;
  font-size: 0.85rem;
}

@media (max-width: 600px) {
  .stat-label {
    min-width: 100px;
    font-size: 0.75rem;
  }

  .stat-info {
    flex-direction: column;
    gap: 4px;
  }
}
